import type { Track } from "./types";

/** Bundled, same-origin demo tracks (generated by scripts/generate-tracks.mjs). */
export const DEMO_TRACKS: Track[] = [
  {
    id: "calibration",
    title: "Calibration Pulse",
    artist: "SyncBeat Lab · 120 BPM click",
    url: "/audio/calibration-pulse.wav",
    bpm: 120,
    durationSec: 60.5,
    hue: "from-cyan-400 via-sky-500 to-indigo-600",
  },
  {
    id: "neon-drive",
    title: "Neon Drive",
    artist: "SyncBeat Lab · Synthwave",
    url: "/audio/neon-drive.wav",
    bpm: 118,
    durationSec: 66.6,
    hue: "from-fuchsia-500 via-pink-500 to-orange-400",
  },
  {
    id: "midnight-lofi",
    title: "Midnight Lo-Fi",
    artist: "SyncBeat Lab · Chillhop",
    url: "/audio/midnight-lofi.wav",
    bpm: 84,
    durationSec: 59.1,
    hue: "from-violet-500 via-purple-600 to-emerald-400",
  },
];

export function findTrackByUrl(url: string | undefined): Track | undefined {
  if (!url) return undefined;
  return DEMO_TRACKS.find((t) => t.url === url);
}

export function hueForUrl(url: string | undefined): string {
  return findTrackByUrl(url)?.hue ?? "from-teal-400 via-cyan-500 to-blue-600";
}
